/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.submit = function () {
    /* sdd-asis-lifecycle:begin fn_submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/submission/searchDisclosureDocument.do?method=selectKorDocumentForEnglish&applNo=" + dma_disclosureVo.get("applNo") + "" + "&formCd=" + dma_disclosureVo.get("formCd") + "&formVer=" + dma_disclosureVo.get("formVer") + "" + "&exmptObjDisclsYn=" + dma_disclosureVo.get("exmptObjDisclsYn") + "";
    $c.win.setPageFrameSrc(null, (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    scwin.close();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_Close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
